import os,re,json,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def f(I):
    H,W=I.shape
    sep=None; vert=None
    # try vertical separator: a column that is constant and nonzero
    for c in range(W):
        col=I[:,c]
        if len(set(col.tolist()))==1 and col[0]!=0:
            vert=c; break
    if vert is None:
        # horizontal separator
        for r in range(H):
            row=I[r]
            if len(set(row.tolist()))==1 and row[0]!=0:
                sep=r; break
    if vert is not None:
        L=I[:,:vert]; R=I[:,vert+1:]
        out=(L!=0)&(R!=0)
        P=np.where(out,2,0)
    else:
        T=I[:sep]; B=I[sep+1:]
        out=(T!=0)&(B!=0)
        P=np.where(out,2,0)
    return P.tolist()
for k in ['Demo pair 1 input','Demo pair 2 input']:
    I=G[k]; O=G[k.replace('input','output')]
    P=f(np.array(I))
    print(k, np.array_equal(np.array(P),np.array(O)))
P=f(np.array(G['Test input']))
